class InvariantViolationError(Exception):
    """Exception raised when a financial invariant is violated."""
    pass


class HighRiskModule15:
    """Financial Invariant Module 15."""

    def validate_invariant(self, payload: dict) -> bool:
        """
        Validates the payload against financial invariants.
        Raises InvariantViolationError if payload.get('valid') is not True.
        """
        if not isinstance(payload, dict) or payload.get('valid') is not True:
            raise InvariantViolationError("Invariant violation: payload is not valid.")
        return True
